 useEffect(()=>{const a=data.active;if(!a)return;const phase=currentPhase(a);const key=`${a.session.id}:${a.index}:${a.state}`;if(announced.current!==key){announced.current=key;setDeclared('');setVoiceUnavailable(!announce(a,profile)&&profile.audio);}
  if(a.state==='working_timed'&&a.remaining<=10&&a.remaining>0&&!thresholds.current.has(phase.id+':10')){thresholds.current.add(phase.id+':10');if(profile.audio)void say('Dix secondes restantes.',profile);}
  if(a.state==='working_timed'&&profile.encouragements&&a.phaseElapsed>=15&&a.remaining>15&&!thresholds.current.has(phase.id+':enc')){thresholds.current.add(phase.id+':enc');if(profile.audio)void say('Garde ton rythme et respire.',profile);}
  if(isRunning(a)&&a.state!=='working_reps'&&a.remaining<=3&&a.remaining>0&&profile.sounds&&(!profile.audio||voiceUnavailable)){const k=phase.id+':'+Math.ceil(a.remaining);if(!thresholds.current.has(k)){thresholds.current.add(k);beep(profile.volume);}}
 },[data.active?.state,data.active?.index,Math.ceil(data.active?.remaining||0),Math.floor(data.active?.phaseElapsed||0),profile.audio]);
