 function exportFile(){const blob=new Blob([storage.exportData({...data,active:activeRef.current})],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`tempo-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url);}
 async function updateResult(s:Session){setResult(s);setData(d=>({...d,sessions:d.sessions.map(x=>x.id===s.id?s:x)}));try{await storage.saveResult(s);setSavedResult(true);}catch(e){setSavedResult(false);fail(e);}}
