 <div className="config-section"><label className="section-label"><span>01</span>Qu’est-ce qu’on travaille ?</label><div className="shortcuts">{([{id:'full',label:'Corps entier',icon:Target},{id:'upper',label:'Haut du corps',icon:Dumbbell},{id:'cardio',label:'Cardio',icon:Flame}] as const).map(s=><button key={s.id} className={(s.id==='full'&&objective==='full'||s.id==='cardio'&&objective==='cardio'||s.id==='upper'&&objective==='muscles'&&zones.length===4&&['pectorals','back','shoulders','arms'].every(z=>zones.includes(z as Zone)))?'shortcut selected':'shortcut'} onClick={()=>{setObjective(s.id==='full'?'full':s.id==='cardio'?'cardio':'muscles');setZones(s.id==='full'?allZones:s.id==='upper'?['pectorals','back','shoulders','arms']:[]);}}><s.icon size={17}/>{s.label}</button>)}</div><div className="zones">{allZones.map(z=><button key={z} aria-pressed={zones.includes(z)} className={zones.includes(z)?'zone selected':'zone'} onClick={()=>{setObjective('muscles');setZones(zones.includes(z)?zones.filter(x=>x!==z):[...zones,z]);}}>{zoneLabels[z]}{zones.includes(z)&&<Check size={15}/>}</button>)}</div><p className="small muted">{objective==='cardio'?'Un objectif cardio, sans sélection musculaire nécessaire.':zones.length?`${zones.length} zone${zones.length>1?'s':''} sélectionnée${zones.length>1?'s':''} · vous pouvez en combiner plusieurs.`:'Choisissez une ou plusieurs zones, ou un raccourci.'}</p></div>
